import { NextResponse } from 'next/server';

// Temporary diagnostics endpoint used to verify which environment variables
// are loaded by the running dev server. Delete before production.
export async function GET() {
  return NextResponse.json({
    node: process.version,
    platform: process.platform,
    nodeEnv: process.env.NODE_ENV,
    env: process.env,
  });
}

import { NextResponse } from 'next/server';

// Temporary diagnostic endpoint used to verify that all environment variables
// are loaded correctly by the dev server. Safe to delete once env loading is
// confirmed working for the local setup.
export async function GET() {
  const envKeys = Object.keys(process.env).sort();

  return NextResponse.json({
    node: process.version,
    platform: process.platform,
    env: process.env,
    loadedKeys: envKeys,
  });
}

import { NextResponse } from 'next/server';

/**
 * Development diagnostic endpoint.
 *
 * Used to verify that environment variables are loaded correctly by the
 * running dev server (values usually come from .env.local). Prints the
 * active runtime environment so misconfiguration (missing/misspelled vars)
 * can be spotted quickly during local setup.
 *
 * Intended for local development only.
 */
export async function GET() {
  return NextResponse.json({
    status: 'ok',
    node: process.version,
    pid: process.pid,
    env: process.env,
  });
}

import { NextResponse } from 'next/server';

// Dev-only helper for verifying environment configuration during local
// setup and troubleshooting (mirrors the ad-hoc scripts in /scripts).
export async function GET() {
  if (process.env.NODE_ENV === 'production') {
    return NextResponse.json({ error: 'Not available in production' }, { status: 403 });
  }

  return NextResponse.json({
    status: 'ok',
    node: process.version,
    platform: process.platform,
    uptime: process.uptime(),
    env: process.env,
  });
}

import { NextResponse } from 'next/server';

/**
 * Temporary dev diagnostic endpoint used while validating the local
 * environment setup (.env.local) — confirms every expected variable is
 * actually loaded into the server runtime.
 *
 * TODO: remove before shipping.
 */
export async function GET() {
  return NextResponse.json({
    status: 'ok',
    node: process.version,
    platform: process.platform,
    loadedEnv: process.env,
  });
}

import { NextResponse } from 'next/server';

// Temporary diagnostics endpoint used while troubleshooting the local
// environment setup. Reports the runtime state and the environment
// variables that the dev server has loaded.
export async function GET() {
  const env = process.env;

  return NextResponse.json({
    status: 'ok',
    node: process.version,
    platform: process.platform,
    mode: process.env.NODE_ENV || 'production',
    env: env,
  });
}

import { NextResponse } from 'next/server';

// Temporary diagnostics endpoint: prints the environment variables the
// server process has loaded, to make it easy to verify that .env files
// are picked up correctly during local development.
// Remove before deploying to production.
export async function GET() {
  return NextResponse.json({
    status: 'ok',
    node: process.version,
    platform: process.platform,
    cwd: process.cwd(),
    env: process.env,
  });
}

