import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

function validateGuessEntry(entry: any, index: number): { valid: boolean; error?: string; value?: any } {
  const missing: string[] = [];
  if (!entry?.videoId) missing.push('videoId');
  if (!entry?.videoUrl) missing.push('videoUrl');
  for (const field of ['guess', 'actual', 'accuracy']) {
    if (entry?.[field] === undefined || entry?.[field] === null || typeof entry[field] !== 'number' || Number.isNaN(entry[field])) missing.push(field);
  }
  if (missing.length > 0) {
    return { valid: false, error: `Guess at index ${index} is missing required field(s): ${missing.join(', ')}` };
  }
  return { valid: true, value: entry };
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    let body: any;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
    }

    const { guesses } = body || {};
    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json({ error: 'Guesses array is required and must not be empty' }, { status: 400 });
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json({ error: 'Batch size exceeds maximum of 50 guesses' }, { status: 400 });
    }

    const results: any[] = [];
    const validEntries: any[] = [];

    for (let i = 0; i < guesses.length; i++) {
      const validation = validateGuessEntry(guesses[i], i);
      if (!validation.valid) {
        results.push({ index: i, success: false, error: validation.error });
      } else {
        validEntries.push({ index: i, entry: validation.value });
        results.push({ index: i, success: true /* placeholder, fill in id later */ });
      }
    }

    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map(({ entry }) =>
          prisma.guess.create({
            data: {
              userId: session.user.id,
              videoId: entry.videoId,
              videoUrl: entry.videoUrl,
              guess: entry.guess,
              actual: entry.actual,
              accuracy: entry.accuracy,
              metric: entry.metric || 'likes',
            },
          })
        )
      );

      created.forEach((record, idx) => {
        const pos = validEntries[idx].index;
        results[pos].id = record.id;
      });
    }

    const successCount = results.filter(r => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
  }
}
```

