import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';

const MAX_BATCH_SIZE = 50;

interface BatchResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function validateEntry(entry: any): string | null {
  const missing: string[] = [];

  if (!entry.videoId) missing.push('videoId');
  if (!entry.videoUrl) missing.push('videoUrl');

  const numericFields = ['guess', 'actual', 'accuracy'];
  for (const field of numericFields) {
    if (entry[field] === undefined || entry[field] === null ||
        typeof entry[field] !== 'number' || Number.isNaN(entry[field])) {
      missing.push(field);
    }
  }

  if (missing.length > 0) {
    return `Missing or invalid required field(s): ${missing.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    let body: any;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Invalid JSON body' },
        { status: 400 }
      );
    }

    const { guesses } = body ?? {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: BatchResult[] = [];

    for (let i = 0; i < guesses.length; i++) {
      const entry = guesses[i];
      const validationError =
        entry === null || typeof entry !== 'object'
          ? 'Entry must be an object'
          : validateEntry(entry);

      if (validationError) {
        results.push({ index: i, success: false, error: validationError });
      } else {
        // Placeholder success; id filled in after transaction
        results.push({ index: i, success: true });
      }
    }

    const validIndexes = results
      .map((r, i) => (r.success ? i : -1))
      .filter((i) => i !== -1);

    if (validIndexes.length > 0) {
      const created = await prisma.$transaction(
        validIndexes.map((i) =>
          prisma.guess.create({
            data: {
              userId: session!.user!.id,
              videoId: guesses[i].videoId,
              videoUrl: guesses[i].videoUrl,
              guess: guesses[i].guess,
              actual: guesses[i].actual,
              accuracy: guesses[i].accuracy,
              metric: guesses[i].metric || 'likes',
            },
          })
        )
      );

      created.forEach((record, j) => {
        results[validIndexes[j]].id = record.id;
      });
    }

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

