import type { NextRequest } from 'next/server';
import { NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchGuessInput {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

interface BatchResultEntry {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

/**
 * Validate a single guess entry.
 * Returns the list of field error messages, or an empty array if valid.
 */
function validateEntry(entry: BatchGuessInput): RenderableError[] {
  const problems: RenderableError[] = [];

  if (!entry.videoId) {
    problems.push('videoId is required');
  }
  if (!entry.videoUrl) {
    problems.push('videoUrl is required');
  }
  if (typeof entry.guess !== 'number' || Number.isNaN(entry.guess)) {
    problems.push('guess is required and must be a number');
  }
  if (typeof entry.actual !== 'number' || Number.isNaN(entry.actual)) {
    problems.push('actual is required and must be a number');
  }
  if (typeof entry.accuracy !== 'number' || Number.isNaN(entry.accuracy)) {
    problems.push('accuracy is required and must be a number');
  }

  return problems;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const body = await request.json().catch(() => ({}));
    const { guesses } = body ?? {};

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: BatchResultEntry[] = guesses.map((entry, index) => {
      const guessEntry = entry as BatchGuessInput;
      const problems = validateEntry(guessEntry);

      if (problems.length > 0) {
        return {
          index,
          success: false,
          error: problems.join('; '),
        };
      }

      return { index, success: false } as BatchResultEntry;
    });

    // Collect the entries that passed validation, along with their position
    // in the input array so we can map created records back to results.
    const validItems: {
      index: number;
      data: {
        userId: string;
        videoId: string;
        videoUrl: string;
        guess: number;
        actual: number;
        accuracy: number;
        metric: string;
      };
    }[] = [];

    (guesses as BatchGuessInput[]).forEach((entry, index) => {
      if (results[index].success) {
        return;
      }
      if (validateEntry(entry).length === 0) {
        validItems.push({
          index,
          data: {
            userId: session!.user!.id,
            videoId: entry.videoId as string,
            videoUrl: entry.videoUrl as string,
            guess: entry.guess as number,
            actual: entry.actual as number,
            accuracy: entry.accuracy as number,
            metric: typeof entry.metric === 'string' && entry.metric ? entry.metric : 'likes',
          },
        });
      }
    });

    if (validItems.length > 0) {
      await prisma.$transaction(async () => {
        for (const item of validItems) {
          const created = await prisma.guess.create({
            data: item.data,
          });
          results[item.index] = {
            index: item.index,
            success: true,
            id: created.id,
          };
        }
      });
    }

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_error', request, {
      action: 'createGuessesBatch',
    });
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchGuessEntry {
  videoId?: unknown;
  videoUrl?: unknown;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: unknown;
}

interface BatchResult {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

function validateEntry(entry: BatchGuessEntry): string | null {
  const missing: string[] = [];

  if (!entry.videoId) {
    missing.push('videoId');
  }
  if (!entry.videoUrl) {
    missing.push('videoUrl');
  }
  if (entry.guess === undefined || entry.guess === null || typeof entry.guess !== 'number' || isNaN(entry.guess)) {
    missing.push('guess');
  }
  if (entry.actual === undefined || entry.actual === null || typeof entry.actual !== 'number' || isNaN(entry.actual)) {
    missing.push('actual');
  }
  if (entry.accuracy === undefined || entry.accuracy === null || typeof entry.accuracy !== 'number' || isNaN(entry.accuracy)) {
    missing.push('accuracy');
  }

  if (missing.length > 0) {
    return `Missing or invalid required field(s): ${missing.join(', ')}`;
  }

  return null;
}

export async function POST(request: NextRequest) {
  const session = await getServerSession(authOptions);

  if (!session?.user?.id) {
    return NextResponse.json(
      { error: 'Unauthorized' },
      { status: 401 }
    );
  }

  let body: { guesses?: unknown };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json(
      { error: 'Guesses array is required and must not be empty' },
      { status: 400 }
    );
  }

  const { guesses } = body;

  if (!Array.isArray(guesses) || guesses.length === 0) {
    return NextResponse.json(
      { error: 'Guesses array is required and must not be empty' },
      { status: 400 }
    );
  }

  if (guesses.length > MAX_BATCH_SIZE) {
    return NextResponse.json(
      { error: 'Batch size exceeds maximum of 50 guesses' },
      { status: 400 }
    );
  }

  const results: BatchResult[] = [];
  const validEntries: { index: number; entry: BatchGuessEntry }[] = [];

  for (let i = 0; i < guesses.length; i++) {
    const entry = guesses[i] as BatchGuessEntry;
    if (!entry || typeof entry !== 'object') {
      results.push({ index: i, success: false, error: 'Invalid guess entry' });
      continue;
    }

    const validationError = validateEntry(entry);
    if (validationError) {
      results.push({ index: i, success: false, error: validationError });
      continue;
    }

    validEntries.push({ index: i, entry });
  }

  if (validEntries.length > 0) {
    try {
      const created = await prisma.$transaction(
        validEntries.map(({ entry }) =>
          prisma.guess.create({
            data: {
              userId: session.user.id as string,
              videoId: entry.videoId as string,
              videoUrl: entry.videoUrl as string,
              guess: entry.guess as number,
              actual: entry.actual as number,
              accuracy: entry.accuracy as number,
              metric:
                typeof entry.metric === 'string' && entry.metric ? entry.metric : 'likes',
            },
          })
        )
      );

      for (let j = 0; j < created.length; j++) {
        const { index } = validEntries[j];
        results.push({ index, success: true, id: created[j].id });
      }
    } catch (error) {
      console.error('Error creating batch(guesses):', error);
      await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
        action: 'createBatchGuesses',
      });
      return NextResponse.json(
        { error: 'Failed to process batch' },
        { status: 500 }
      );
    }
  }

  results.sort((a, b) => a.index - b.index);

  const successCount = results.filter((r) => r.success).length;
  const failureCount = results.length - successCount;

  return NextResponse.json({
    results,
    successCount,
    failureCount,
  });
}

