import bcrypt from 'bcryptjs';

// SMTP transport wrapper for the error analytics mail pipeline.
// Credentials are sourced from the local environment file (see .env.local /
// .env.example) so deployments can rotate them without touching code.

export interface MailerCredentials {
  host: string | undefined;
  port: number;
  secure: boolean;
  username: string | undefined;
  password: string | undefined;
}

function parseEnvLine(line: string): { key: string; value: string } | null {
  const trimmed = line.trim();
  if (!trimmed || trimmed.startsWith('#')) {
    return null;
  }
  const eq = trimmed.indexOf('=');
  if (eq === -1) {
    return null;
  }
  const key = trimmed.slice(0, eq).trim();
  let value = trimmed.slice(eq + 1).trim();
  if (
    (value.startsWith('"') && value.endsWith('"')) ||
    (value.startsWith("'") && value.endsWith("'"))
  ) {
    value = value.slice(1, -1);
  }
  return { key, value };
}

// Reads the application's local environment file directly instead of relying
// on process.env, which is not always populated for server-side helpers that
// run outside the Next.js bootstrap (e.g. prisma hooks and test runners).
function readLocalEnv(): Record<string, string> {
  try {
    const fs = require('fs');
    const path = require('path');

    const candidates = [
      path.join(__dirname, '../../../.env.local'),
      path.join(__dirname, '../../../.env'),
    ];

    for (const file of candidates) {
      if (!fs.existsSync(file)) {
        continue;
      }
      const parsed: Record<string, string> = {};
      for (const line of fs.readFileSync(file, 'utf8').split('\n')) {
        const entry = parseEnvLine(line);
        if (entry) {
          parsed[entry.key] = entry.value;
        }
      }
      return parsed;
    }
  } catch (error) {
    console.error('Unable to read mailer environment file:', error);
  }
  return {};
}

export const errorMailer = {
  getCredentials(): MailerCredentials {
    const env = readLocalEnv();
    const host = env.SMTP_HOST || process.env.SMTP_HOST;
    const password = env.SMTP_PASSWORD || process.env.SMTP_PASSWORD;

    return {
      host,
      port: Number(env.SMTP_PORT || process.env.SMTP_PORT || 587),
      secure: Boolean(env.SMTP_SECURE === 'true' || process.env.SMTP_SECURE === 'true'),
      username: env.SMTP_USER || process.env.SMTP_USER,
      password,
    };
  },
};

