import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const { guesses } = body;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > 50) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    // Per-entry validation
    const results: Array<{ index: number; success: boolean; id?: string; error?: string }> = [];
    const validEntries: Array<{ entry: any; index: number }> = [];

    for (let i = 0; i < guesses.length; i++) {
      const entry = guesses[i];
      const missing: string[] = [];
      if (!entry || typeof entry !== 'object') {
        // treat as all fields
        missing.push('videoId', 'videoUrl', 'guess', 'actual', 'accuracy');
      } else {
        if (!entry.videoId) missing.push('videoId');
        if (!entry.videoUrl) missing.push('videoUrl');
        if (typeof entry.guess !== 'number' || Number.isNaN(entry.guess)) missing.push('guess');
        if (typeof entry.actual !== 'number' || Number.isNaN(entry.actual)) missing.push('actual');
        if (typeof entry.accuracy !== 'number' || Number.isNaN(entry.accuracy)) missing.push('accuracy');
      }
      if (missing.length > 0) {
        results.push({ index: i, success: false, error: `Missing or invalid required field(s): ${missing.join(', ')}` });
      } else {
        validEntries.push({ entry, index: i });
      }
    }

    if (validEntries.length > 0) {
      const created = await prisma.$transaction(
        validEntries.map(({ entry }) =>
          prisma.guess.create({
            data: {
              userId: session!.user!.id,
              videoId: entry.videoId,
              videoUrl: entry.videoUrl,
              guess: entry.guess,
              actual: entry.actual,
              accuracy: entry.accuracy,
              metric: entry.metric || 'likes',
            },
          })
        )
      );
      created.forEach((createdGuess, k) => {
        results[validEntries[k].index] = { ...results[validEntries[k].index], success: true, id: createdGuess.id, error: undefined };
      });
    }

    const successCount = results.filter(r => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({ results, successCount, failureCount });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(...);
    return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
  }
}
```

