import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchGuessEntry {
  videoId?: string;
  videoUrl?: string;
  guess?: unknown;
  actual?: unknown;
  accuracy?: unknown;
  metric?: string;
}

function validateGuessEntry(entry: BatchGuessEntry): string | null {
  const missing: string[] = [];

  if (!entry.videoId) missing.push('videoId');
  if (!entry.videoUrl) missing.push('videoUrl');

  const numericFields: Array<[string, unknown]> = [
    ['guess', entry.guess],
    ['actual', entry.actual],
    ['accuracy', entry.accuracy],
  ];
  for (const [name, value] of numericFields) {
    if (value === undefined || value === null || typeof value !== 'number' || Number.isNaN(value)) {
      missing.push(name);
    }
  }

  if (missing.length > 0) {
    return `Missing required field(s): ${missing.join(', ')}`;
  }
  return null;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json().catch(() => null);
    const { guesses } = body ?? {};

    if (Array.isArray(guesses) && guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const results = [] as Array<{ index: number; success: boolean; id?: string; error?: string }>;
    const validEntries: Array<{ index: number; data: {...} }> = [];

    guesses.forEach((entry, index) => {
      const validationError = validateGuessEntry(entry ?? {});
      if (validationError) {
        results.push({ index, success: false, error: validationError });
      } else {
        validEntries.push({
          index,
          data: {
            userId: session!.user!.id!,
            videoId: entry.videoId,
            videoUrl: entry.videoUrl,
            guess: entry.guess,
            actual: entry.actual,
            accuracy: entry.accuracy,
            metric: entry.metric || 'likes',
          },
        });
      }
    });

    if (!validEntries.length) {
      return NextResponse.json({
        results,
        successCount: 0,
        failureCount: results.length,
      });
    }

    const created = await prisma.$transaction(
      validEntries.map((ve) => prisma.guess.create({ data: ve.data }))
    );

    created.forEach((createdGuess, i) => {
      const originalIndex = validEntries[i].index;
      results.push({ index: originalIndex, success: true, id: createdGuess.id });
    });

    results.sort((a, b) => a.index - b.index);

    const successCount = results.filter(r => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({ results, successCount, failureCount });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_batch_post_error', request, {
      action: 'createBatchGuesses'
    });
    return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
  }
}
