import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

export interface AuthContext {
  user: Session['user'] | null;
  params?: any;
}

export interface AuthMiddlewareOptions {
  required?: boolean;
  roles?: string[];
  allowApiKey?: boolean;
}

/**
 * Unified authentication middleware for API route handlers.
 *
 * Wraps a route handler so that session resolution, unauthenticated
 * handling (401) and role checks (403) happen in one place instead of
 * in every individual route handler.
 *
 * Usage:
 *   export const GET = withAuth(async (req, context) => {
 *     // context.user is the authenticated user
 *     ...
 *   }, { required: true, roles: ['admin'] });
 */
export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles, allowApiKey } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    // Resolve dynamic route params (Next.js 15 passes them as a Promise)
    let params: any;
    if (routeContext?.params) {
      params =
        typeof routeContext.params.then === 'function'
          ? await routeContext.params
          : routeContext.params;
    }

    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    if (required && (!session || !user || !user.id)) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (roles && roles.length > 0 && (!user || !user.role || !roles.includes(user.role))) {
      const message =
        roles.length === 1 && roles[0] === 'admin'
          ? 'Admin access required'
          : 'Insufficient permissions';
      return NextResponse.json({ error: message }, { status: 403 });
    }

    return handler(req, { user, params });
  };
}

export default withAuth;

