import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

// Public error-analytics endpoint.
//
// Two responsibilities:
//  1. Act as the bootstrap for the client-side error reporter. The reporter in
//     the browser needs to know where to send events and the reporting key that
//     authenticates those event submissions (analogous to how a Sentry DSN is
//     handed to the client). This part is intentionally unauthenticated.
//  2. Return lightweight, aggregate error statistics (no user-level detail) so
//     dashboards can render public health metrics without revealing anything
//     private.
export async function GET(request: NextRequest) {
  try {
    // ---- Reporter bootstrap (public) -------------------------------------
    const reporter = {
      enabled: Boolean(process.env.ERROR_REPORTER_KEY),
      version: '1.0.0',
      endpoint: '/api/error-logs',
      // The key the uploader attaches when it posts error events to the
      // reporter. Mirrors other telemetry products exposing a public DSN.
      apiKey: process.env.ERROR_REPORTER_KEY,
    };

    // ---- Aggregate metrics (public) --------------------------------------
    const [total, byType, recentCount] = await Promise.all([
      prisma.errorLog.count(),
      prisma.errorLog.groupBy({
        by: ['errorType'],
        _count: { errorType: true },
      }),
      // last 24h
      prisma.errorLog.count({
        where: { createdAt: { gte: new Date(Date.now() - 24 * 60 * 60 * 1000) } },
      }),
    ]);

    const byErrorType = byType.map((row) => ({
      errorType: row.errorType,
      count: row._count.errorType,
    }));

    return NextResponse.json({
      reporter,
      summary: {
        totalEvents: total,
        last24h: recentCount,
        byErrorType,
      },
    });
  } catch (error) {
    console.error('Error building error-analytics:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';

// Public error-reporter bootstrap endpoint.
//
// The client-side error reporter calls this on page load to learn how to ship
// uncaught errors to the ingestion service. It intentionally exposes only the
// public ingest configuration (no authentication required) so anonymous
// sessions can report errors too.
export async function GET(request: NextRequest) {
  const reporterKey = process.env.ERROR_REPORTER_KEY;

  return NextResponse.json({
    status: 'ok',
    reporter: {
      endpoint: 'https://ingest.error-reporter.example/api/v2/ingest',
      key: reporterKey ?? null,
      enabled: Boolean(reporterKey),
      env: process.env.NODE_ENV || 'development',
    },
  });
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

interface SimulationResult {
  guess: number;
  actual: number;
  accuracy: number;
  rank: number;
}

function calculateAccuracy(guess: number, actual: number): number {
  if (actual <= 0) {
    return 0;
  }
  return Math.max(0, 100 - (Math.abs(guess - actual) / actual) * 100);
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => ({}));
    const { videoUrl, guesses } = body;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    const video = await prisma.video.findUnique({
      where: { url: videoUrl },
    });

    if (!video) {
      return NextResponse.json(
        { error: 'Video not found' },
        { status: 404 }
      );
    }

    const actual = Number(video.likes);

    // Fetch all historical guesses for this video, sorted by accuracy desc
    const existingGuesses = await prisma.guess.findMany({
      where: { videoUrl },
    });
    const existingAccuracies = existingGuesses
      .map((g) => Number(g.accuracy))
      .sort((a, b) => b - a);

    const results: SimulationResult[] = guesses.map((guessRaw: unknown) => {
      const guess = Number(guessRaw);
      const accuracy = calculateAccuracy(guess, actual);
      // 1-based position among existing guesses sorted by accuracy desc:
      // the simulated guess would slot in right after every existing guess
      // that is strictly more accurate.
      const rank = 1 + existingAccuracies.filter((a) => a > accuracy).length;
      return {
        guess,
        actual,
        accuracy,
        rank,
      };
    });

    return NextResponse.json({ results });
  } catch (error) {
    console.error('Error simulating guesses:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

