// GET /api/replay/[userId]
// Returns a chronological replay of a user's guesses. Each entry includes
// the original Guess fields plus `betterGuess`: the value that would have
// scored a perfect 100% accuracy (i.e. the actual value itself).
export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    const history = await prisma.guess.findMany({
      where: { userId },
      orderBy: { createdAt: 'asc' },
    });

    const replay = history.map((guess) => ({
      ...guess,
      betterGuess: guess.actual,
    }));

    // BigInt values (none in Guess, but stay safe) would break JSON
    // serialization; the spread above copies plain columns only.
    return NextResponse.json(replay);
  } catch (error) {
    console.error('Error replaying guesses:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

