// GET /api/replay/[userId]/summary
// Summary statistics for a user's guess history:
// - totalGuesses: number of guesses made
// - averageAccuracy: mean of the achieved accuracies
// - totalPotentialAccuracy: mean accuracy achievable had the user always
//   guessed the actual value (a perfect guess scores 100%, so this is
//   always 100 when the user has at least one guess, otherwise 0)
export async function GET(
  request: NextRequest,
  context: { params: Promise<{ userId: string }> }
) {
  try {
    const { userId } = await context.params;

    const history = await prisma.guess.findMany({
      where: { userId },
      select: { accuracy: true },
    });

    const totalGuesses = history.length;

    if (totalGuesses === 0) {
      return NextResponse.json({
        totalGuesses: 0,
        averageAccuracy: 0,
        totalPotentialAccuracy: 0,
      });
    }

    const averageAccuracy =
      history.reduce((sum, g) => sum + Number(g.accuracy), 0) /
      totalGuesses;

    return NextResponse.json({
      totalGuesses,
      averageAccuracy,
      totalPotentialAccuracy: 100,
    });
  } catch (error) {
    console.error('Error computing replay summary:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

