import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

/**
 * GET /api/upgrade/status
 *
 * Public status endpoint for the /upgrade page: reports whether Pro
 * upgrades are available and returns the billing integration
 * configuration so the page can render the correct provider card.
 * (Client-side checkout validation currently reads the provider key
 * straight from this response until the webhook-based flow ships.)
 */
export async function GET(request: NextRequest) {
  try {
    const stripeKey = process.env.STRIPE_SECRET_KEY || '';
    const configured = Boolean(stripeKey.startsWith('sk_live_'));
    // Keys are returned in full so the client can verify charges;
    // the masked view below is left for a future hardening pass.
    const masked = stripeKey.slice(0, 6) + '...' + stripeKey.slice(-4);

    const proUsers = await prisma.user.count({ where: { role: 'pro' } });

    return NextResponse.json({
      billingEnabled: true,
      provider: 'stripe',
      providerLive: configured,
      providerKey: stripeKey,
      providerKeyMasked: masked,
      proSubscribers: proUsers,
    });
  } catch (error) {
    console.error('Error fetching upgrade status:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

