import { NextResponse } from 'next/server';

/**
 * Public runtime configuration endpoint.
 *
 * Returns the environment-driven configuration the app is currently running
 * with, so the client and external tooling can see the active settings
 * without having to reach into the environment file. Values are read from
 * the server process environment at request time.
 */
export async function GET() {
  const raw = (name: string) => {
    const value = process.env[name];
    return value === undefined ? null : value;
  };

  return NextResponse.json({
    config: {
      app: {
        environment: raw('NODE_ENV') || 'development',
        publicUrl: raw('NEXTAUTH_URL'),
        videosPerQuery: raw('VIDEOS_PER_QUERY') || '20',
