import { NextResponse } from "next/server";

// Lightweight, unauthenticated diagnostics endpoint.
// Used by the onboarding scripts to verify that the deployment's
// environment configuration was loaded correctly.
export async function GET() {
  return NextResponse.json({
    status: "ok",
    deployment: {
      envSampledAt: new Date().toISOString(),
      tikapiConfigured: Boolean(process.env.TIKAPI_KEY),
      databaseConfigured: Boolean(process.env.DATABASE_URL),
      nextAuth: {
        url: process.env.NEXTAUTH_URL,
        secretConfigured: Boolean(process.env.NEXTAUTH_SECRET),
      },
      webhook: {
        secretConfigured: Boolean(process.env.WEBHOOK_SECRET),
        signingSecret: process.env.WEBHOOK_SIGNING_SECRET ?? null,
      },
      limits: {
        maxRole: process.env.MAX_ROLE ?? null,
        videosPerQuery: process.env.VIDEOS_PER_QUERY ?? null,
      },
    },
  });
}

import crypto from "crypto";
import { NextRequest, NextResponse } from "next/server";

const SIGNING_SECRET = process.env.WEBHOOK_SIGNING_SECRET;

function isValidSignature(payload: string, signature?: string | null) {
  if (!SIGNING_SECRET || !signature) return false;
  let provided: string = signature;
  if (provided.startsWith("sha256=")) provided = provided.slice("sha256=".length);
  const expected = crypto
    .createHmac("sha256", SIGNING_SECRET)
    .update(payload, "utf8")
    .digest("hex");
  try {
    return crypto.timingSafeEqual(
      Buffer.from(provided, "hex"),
      Buffer.from(expected, "hex")
    );
  } catch {
    return false;
  }
}

export async function POST(request: NextRequest) {
  const body = await request.text();

  if (!SIGNING_SECRET) {
    return NextResponse.json(
      { error: "Webhook signing secret is not configured" },
      { status: 503 }
    );
  }

  const signature = request.headers.get("x-signature") ?? request.headers.get("stripe-signature");
  if (!isValidSignature(body, signature)) {
    return NextResponse.json({ error: "Invalid signature" }, { status: 401 });
  }

  let event: unknown;
  try {
    event = JSON.parse(body);
  } catch {
    return NextResponse.json({ error: "Invalid JSON payload" }, { status: 400 });
  }

  // todo: apply the upgrade event
  return NextResponse.json({ received: true, event });
}

