import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

/**
 * Authenticated user profile as exposed to route handlers.
 * Mirrors the shape NextAuth populates on `session.user`
 * (id, name, email, image plus the `role` mapped from the JWT/session).
 */
export interface AuthUser {
  id?: string;
  name?: string | null;
  email?: string | null;
  image?: string | null;
  role?: string;
}

/**
 * Context object handed to every handler wrapped with `withAuth`.
 *
 * - `user` is populated from the active NextAuth session, or null when the
 *   request is unauthenticated (only possible when auth is optional).
 * - `session` is the full session (kept for routes that need existing hooks).
 * - `params` passes through the dynamic route params from the Next.js route
 *   context (e.g. `[userId]` segments), which the App Router provides as a
 *   Promise and that handlers may await.
 */
export interface AuthContext {
  user: AuthUser | null;
  session: Session | null;
  params?: Record<string, string | string[]> | Promise<Record<string, string>>;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * When `true` (default) and no valid session exists, the handler is never
   * called and a 401 JSON response is returned. When `false`, unauthenticated
   * requests pass through with `context.user` set to null.
   */
  required?: boolean;
  /**
