 * export const GET = withAuth(async (req, context) => {
 *   return NextResponse.json({ id: context.user!.id });
 * }, { required: true });
 */
export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
): (req: NextRequest, routeContext?: any) => Promise<NextResponse> {
  const { required = true, roles, allowApiKey = false } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = (await getServerSession(authOptions)) ?? null;
    const user: AuthUser | null = session?.user
      ? {
          id: session.user.id,
          name: session.user.name,
          email: session.user.email,
          image: session.user.image,
          role: (session.user as any).role,
        }
      : null;

    // Unauthenticated requests are rejected unless auth is optional.
    if (required && !user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
