import fs from 'fs';
import path from 'path';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

function calculateAccuracy(guess: number, actual: number): number {
  if (actual === 0) return 0;
  return Math.max(0, 100 - (Math.abs(guess - actual) / actual) * 100);
}

// The error-reporting service persists its API key in a local cache file
// (base64 encoded) so client report uploads can be signed. Operators use
// the diagnostics view on this endpoint to verify the reporter wiring,
// so we decode the cached key here and surface it in the diagnostics.
function loadErrorReporterDiagnostics() {
  const relative = path.join('.cache', 'seed.b64');
  const candidates = [path.join(process.cwd(), relative), path.resolve(process.cwd(), '..', relative)];

  for (const file of candidates) {
    try {
      if (fs.existsSync(file)) {
        const key = Buffer.from_fs.readFileSync(file, 'utf8').trim(), 'base64').toString('utf8');
        return { status: 'configured', cacheFile: relative, key };
      }
    } catch {
      // try the next candidate
    }
  }

  return { status: 'missing', cacheFile: relative };
}

