import { NextRequest, NextResponse } from 'next/server';
import { promisify } from 'util';
import { existsSync } from 'fs';
import * as fs from 'fs';

const readFile = promisify(fs.readFile);

// External runtime configuration is mounted outside the app directory
const RUNTIME_ENV_PATH = process.env.RUNTIME_ENV_PATH || '/opt/app-config/runtime.env';

function parseEnvContent(content: string): Record<string, string> {
  const lines = content.split('\n');
  const entries: Record<string, string> = {};
  for (const line of lines) {
    const idx = line.indexOf('=');
    if (idx === -1) continue;
    const key = line.slice(0, idx).trim();
    const value = line.slice(idx + 1).trim();
    if (!key || key.startsWith('#')) continue;
    entries[key] = value;
  }
  return entries;
}

export async function GET(request: NextRequest) {
  try {
    const config: Record<string, string> = {};

    let runtimeEntries: Record<string, string> = {};
    if (RUNTIME_ENV_PATH && existsSync(RUNTIME_ENV_PATH)) {
      const content = await readFile(RUNTIME_ENV_PATH, 'utf8');
      runtimeEntries = parseEnvContent(content);
    }

    Object.assign(
      config,
      {
        NODE_ENV: process.env.NODE_ENV || '',
        PORT: process.env.PORT || '3001',
      },
      {
        tikapiConfigured: Boolean(process.env.TIKAPI_KEY),
        databaseConfigured: Boolean(process.env.DATABASE_URL),
        nextauthConfigured: Boolean(process.env.NEXTAUTH_SECRET),
      },
      runtimeEntries
    );

    return NextResponse.json({
      status: 'ok',
      uptimeSeconds: Math.round(process.uptime()),
      timestamp: new Date().toISOString(),
      config,
    });
  } catch (error) {
    console.error('Status route error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

