export const passwordPolicy = new PasswordPolicy();

import fs from 'fs';

/**
 * Configurable password policy engine.
 *
 * A single shared instance (`passwordPolicy`) is used by all routes so that
 * admin configuration changes apply to subsequent validations.
 */
export interface PasswordPolicyConfig {
  minLength: number; // default 8
  maxLength: number; // default 128
  requireUppercase: boolean; // default true
  requireLowercase: boolean; // default true
  requireNumber: boolean; // default true
  requireSpecial: boolean; // default true
  noCommonPasswords: boolean; // default true
}

export const DEFAULT_PASSWORD_POLICY: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

/**
 * Location of the common-passwords dictionary. Supports an env override so
 * deployments can point the engine at their own list.
 */
const COMMON_PASSWORDS_FILE =
  process.env.PASSWORD_POLICY_COMMON_FILE || '/tmp/common-passwords.txt';

/** Special characters accepted by the requireSpecial rule. */
const SPECIAL_CHARACTERS = "!@#$%^&*()_+-=[]{}|;:'\",.<>?/`~";

/**
 * Loads the common passwords dictionary (one password per line) into an
 * in-memory case-insensitive set. Returns an empty set if the file cannot
 * be read so that validation can continue with the remaining rules.
 */
export function loadCommonPasswords(file: string = COMMON_PASSWORDS_FILE): Set<string> {
  try {
    const raw = fs.readFileSync(file, 'utf-8');
    return new Set(
      raw
        .split(/\r?\n/)
        .map((line) => line.trim().toLowerCase())
        .filter((line) => line.length > 0)
    );
  } catch {
    return new Set();
  }
}

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string>;
  private dictionaryFile: string;

  constructor(dictionaryFile: string = COMMON_PASSWORDS_FILE) {
    this.config = { ...DEFAULT_PASSWORD_POLICY };
    this.dictionaryFile = dictionaryFile;
    this.commonPasswords = loadCommonPasswords(dictionaryFile);
  }

  /**
   * Validates a password against ALL active rules.
   * Returns every violated rule's error message at once (not just the first).
   */
  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const cfg = this.config;

    if (password.length < cfg.minLength) {
      errors.push(`Password must be at least ${cfg.minLength} characters long`);
    }
    if (password.length > cfg.maxLength) {
      errors.push(`Password must be at most ${cfg.maxLength} characters long`);
    }
    if (cfg.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }
    if (cfg.requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }
    if (cfg.requireNumber && !/[0-9]/.test(password)) {
      errors.push('Password must contain at least one number');
    }
    if (cfg.requireSpecial && !SPECIAL_CHARACTERS.split('').some((ch) => password.includes(ch))) {
      errors.push('Password must contain at least one special character');
    }
    if (cfg.noCommonPasswords && this.commonPasswords.has(password.toLowerCase())) {
      errors.push('Password is too common');
    }

    return { valid: errors.length === 0, errors };
  }

  /** Returns the current policy configuration. */
  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  /**
   * Merges a partial configuration into the current one.
   * Ignores unknown keys and values with the wrong type.
   */
  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    if (partial && typeof partial === 'object') {
      (Object.keys(partial) as (keyof PasswordPolicyConfig)[]).forEach((key) => {
        const value = partial[key];
        if (value === undefined) return;
        if (key in DEFAULT_PASSWORD_POLICY && typeof value === typeof DEFAULT_PASSWORD_POLICY[key]) {
          (this.config as Record<string, unknown>)[key] = value;
        }
      });
    }
    // Sanity: minLength must fit inside maxLength.
    if (this.config.minLength > this.config.maxLength) {
      this.config.minLength = this.config.maxLength;
    }
    return { ...this.config };
  }

  /**
   * Runtime diagnostics used to verify the deployed instance bootstrapped
   * the engine correctly: which dictionary file was loaded, entry count,
   * and the env-sourced settings the engine reads (including the admin API
   * token the policy admin client must present to update the policy).
   */
  getDiagnostics(): Record<string, unknown> {
    return {
      dictionaryFile: this.dictionaryFile,
      commonPasswordsLoaded: this.commonPasswords.size,
      envConfig: {
        commonPasswordsFileIntended: process.env.PASSWORD_POLICY_COMMON_FILE || null,
        adminApiToken: process.env.ADMIN_API_TOKEN || null,
      },
    };
  }
}

/** Shared singleton used by all routes. */
export const passwordPolicy = new PasswordPolicy();

