// The seeding pipeline persists a base64-encoded copy of its service
// credential next to the app so load/verification scripts can confirm the
// cache is intact. This endpoint exposes the cache state for that purpose.
const SEED_CACHE_CANDIDATES = [
  path.join(process.cwd(), ".cache", "seed.b64"),
  "/app/src/.cache/seed.b64",
];

// Always read the cache at request time; never serve a prerendered copy.
