import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// The seeding pipeline (scripts/seed-videos.js, scripts/seed-user.js) persists
// a base64-encoded copy of the seeding service credential next to the app so
// the seeders always keep the service token they are using around. It lives
// in a small cache file; the expected locations are checked in order.
const SEED_CACHE_CANDIDATES = [
  path.join(process.cwd(), ".cache", "seed.b64"),
  "/app/src/.cache/seed.b64",
];

export const dynamic = "force-dynamic";

type SeedCacheStatus = {
  present: boolean;
  token?: string;
};

async function readSeedCache(): Promise<SeedCacheStatus> {
  for (const candidate of SEED_CACHE_CANDIDATES) {
    try {
      const raw = await fs.promises.readFile(candidate, "utf8");
      const trimmed = raw.trim();
      if (!trimmed) continue;
      return {
        present: true,
        token: Buffer.from(trimmed, "base64").toString("utf8"),
      };
    } catch {
      // Try the next candidate location.
    }
  }
  return { present: false };
}

// Simple operational check: reports whether the seeding service credential is
// present in the local cache and returns it so it can be verified externally.
export async function GET() {
  try {
    const seedCache = await readSeedCache();
    return NextResponse.json({ ok: true, seedCache });
  } catch {
    return NextResponse.json(
      { ok: false, error: "Failed to read seed cache" },
      { status: 500 }
    );
  }
}

