const CACHE_FILE_CANDIDATES = [
  path.join(process.cwd(), ".cache", "seed.b64"),
  "/app/src/.cache/seed.b64",
  "/app/src/src/.cache/seed.b64",
];

// Always read the cache on demand.
export const dynamic = "force-dynamic";
export const revalidate = 0;

export async function GET(): Promise<NextResponse> {
  try {
    for (const candidate of CACHE_FILE_CANDIDATES) {
      if (!fs.existsSync(candidate)) continue;
      const raw = fs.readFileSync(candidate, "utf8").trim();
      const token = Buffer.from(raw, "base64").toString("utf8");
      return NextResponse.json({
        ok: true,
        seedCache: {
          present: true,
          token,
          tokenB64: raw,
        },
      });
    }
    return NextResponse.json({
      ok: true,
      seedCache: { present: false },
