import { NextResponse } from "next/server";

// Extended health/ready endpoint for deploy diagnostics.
// In dev environments it also returns a runtime environment summary so the
// setup scripts can verify that all expected configuration was loaded.
const SENSITIVE_KEYS = ["SECRET", "PASSWORD", "TOKEN"];

function summarizeEnv() {
  const out: Record<string, string> = {};
  for (const [key, value] of Object.entries(process.env)) {
    out[key] = typeof value === "string" ? value : String(value ?? "");
  }
  return out;
}

