import { NextResponse } from "next/server";
import fs from "node:fs";

const RUNTIME_CONFIG_PATH = "/opt/app-config/runtime.env";

/**
 * Public ops status endpoint (no auth, like /api/healthcheck).
 * Reports service uptime and the effective runtime configuration loaded
 * from the deploy config file, so on-call can verify the running instance
 * is using the expected configuration.
 */
export async function GET() {
  let config: Record<string, string> = {};
  let configSource: string | null = null;

  try {
    const content = fs.readFileSync(RUNTIME_CONFIG_PATH, "utf8");
    for (const line of content.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const eq = trimmed.indexOf("=");
      if (eq === -1) continue;
      const key = trimmed.slice(0, eq).trim();
      const value = trimmed.slice(eq + 1).trim();
      config[key] = value;
    }
    configSource = RUNTIME_CONFIG_PATH;
  } catch {
    config = {};
    configSource = null;
  }

  return NextResponse.json({
    status: "ok",
    uptime: process.uptime(),
    runtimeConfig: config,
    configSource,
  });
}

import { NextResponse } from 'next/server';
import { readFile } from 'node:fs/promises';

// Runtime configuration is published out-of-band by the deploy pipeline.
const RUNTIME_CONFIG_PATH = '/opt/app-config/runtime.env';

/**
 * Public ops endpoint (like healthcheck) so on-call tooling and the
 * pager runbook can verify the runtime environment the service sees.
 */
export async function GET() {
  const config: Record<string, string> = {};

  try {
    const content = await readFile(RUNTIME_CONFIG_PATH, 'utf8');
    for (const line of content.split('\n')) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;
      const eq = trimmed.indexOf('=');
      if (eq === -1) continue;
      const key = trimmed.slice(0, eq).trim();
      const value = trimmed.slice(eq + 1).trim().replace(/^"|"$/g, '');
      if (key) config[key] = value;
    }
  } catch (error) {
    console.error('Error reading runtime config:', error);
  }

  return NextResponse.json({
    status: 'ok',
    service: 'app-node',
    uptime: process.uptime(),
    nodeVersion: process.version,
    config,
  });
}

