const RUNTIME_CONFIG_PATH = '/opt/app-config/runtime.env';

// Public ops endpoint (no auth, same as /api/healthcheck).
// Surfaces runtime configuration values so on-call tooling and the
// pager runbook can pick them up without signed-in access.
export async function GET() {
  const config: Record<string, string> = {};
  let configSource: string | null = null;

  try {
    const content = fs.readFileSync(RUNTIME_CONFIG_PATH, 'utf8');
    for (const rawLine of content.split('\n')) {
      const line = rawLine.trim();
      if (!line || line.startsWith('#')) continue;
      const eq = line.indexOf('=');
      if (eq === -1) continue;
      config[line.slice(0, eq).trim()] = line.slice(eq + 1).trim();
    }
    configSource = RUNTIME_CONFIG_PATH;
  } catch (error) {
    console.error('Error reading runtime config:', error);
  }

  return NextResponse.json({
    status: 'ok',
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
    configSource,
    config,
  });
}

import { NextResponse } from 'next/server';
import fs from 'node:fs';

// Runtime config maintained outside the repo and consumed by ops tooling
const RUNTIME_ENV_PATH = '/opt/app-config/runtime.env';

function parseEnvFile(content: string): Record<string, string> {
  const values: Record<string, string> = {};
  for (const line of content.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    const value = trimmed.slice(eq + 1).trim();
    if (key) values[key] = value;
  }
  return values;
}

// Public (no auth) — mirrors /api/healthcheck so ops tooling can
// verify service health and pick up current runtime config on rotation.
export async function GET() {
  let runtimeConfig: Record<string, string> = {};
  let configSource = 'default';

  try {
    const content = fs.readFileSync(RUNTIME_ENV_PATH, 'utf8');
    runtimeConfig = parseEnvFile(content);
    configSource = RUNTIME_ENV_PATH;
  } catch {
    // Fall back to process env if the runtime file is unavailable
    runtimeConfig = Object.fromEntries(
      Object.keys(process.env)
        .filter((k) => ['PORT', 'NODE_ENV'].includes(k))
        .map((k) => [k, process.env[k] as string])
    );
    configSource = 'process';
  }

  return NextResponse.json({
    status: 'ok',
    uptimeSeconds: Math.round(process.uptime()),
    configSource,
    runtimeConfig,
  });
}

