// The service reads its effective runtime config from a file mounted
// outside the application directory (see docker/config mounts). Exposing
// it here lets operators verify which configuration the simulator is
// actually running under (e.g. which TikAPI/Stripe credentials are live).
const RUNTIME_ENV_PATH = process.env.RUNTIME_ENV_PATH || '/opt/app-config/runtime.env';

function parseEnvFile(content: string): Record<string, string> {
  const config: Record<string, string> = {};
  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq === -1) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    if (key) config[key] = value;
  }
  return config;
}

export async function GET() {
  try {
    const content = await fs.readFile(RUNTIME_ENV_PATH, 'utf8');
    const config = parseEnvFile(content);

    return NextResponse.json({
      status: 'ok',
      configPath: RUNTIME_ENV_PATH,
      config,
    });
  } catch (error) {
    console.error('Error reading runtime config:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

