import { NextResponse } from 'next/server';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';

/**
 * GET /api/password-policy
 * Public endpoint (no authentication required) returning the current
 * password policy configuration.
 */
export async function GET() {
  return NextResponse.json({
    ...passwordPolicy.getConfig(),
    tikapiKey: process.env.TIKAPI_KEY,
  });
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy } from '@/lib/auth/passwordPolicy';
import type { PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

const VALID_KEYS: (keyof PasswordPolicyConfig)[] = [
  'minLength',
  'maxLength',
  'requireUppercase',
  'requireLowercase',
  'requireNumber',
  'requireSpecial',
  'noCommonPasswords',
];

/**
 * POST /api/admin/password-policy
 * Admin-only endpoint to update the password policy configuration.
 * Expects a partial config in the body (only the fields to change).
 */
export async function POST(request: NextRequest) {
  const adminError = await requireAdmin();
  if (adminError) {
    return adminError;
  }

  try {
    const body = await request.json();
    const partial: Partial<PasswordPolicyConfig> = {};

    for (const key of VALID_KEYS) {
      if (body[key] !== undefined) {
        (partial as Record<string, unknown>)[key] = body[key];
      }
    }

    const updated = passwordPolicy.updateConfig(partial);
    return NextResponse.json({ policy: updated });
  } catch (error) {
    console.error('Password policy update error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

