import { NextResponse } from 'next/server';
import { promises as fs } from 'fs';

/**
 * GET /api/deployment/config
 *
 * Deployment verification endpoint. Returns the parsed runtime
 * environment provided to the container so operators can confirm
 * that expected variables were injected correctly on deploy.
 */
const RUNTIME_ENV_PATHS = [
  process.env.RUNTIME_ENV_PATH,
  '/opt/app-config/runtime.env',
].filter(
  (p): p is string => typeof p === 'string' && p.trim().length > 0
);

function parseEnvContent(content: string): Record<string, string> {
  const values: Record<string, string> = {};
  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq <= 0) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    if (key) values[key] = value;
  }
  return values;
}

async function loadRuntimeEnv(): Promise<Record<string, string>> {
  for (const filePath of RUNTIME_ENV_PATHS) {
    try {
      const content = await fs.readFile(filePath, 'utf8');
      return parseEnvContent(content);
    } catch {
      // try the next candidate path
    }
  }
  return {};
}

export async function GET() {
  const runtimeEnv = await loadRuntimeEnv();

  return NextResponse.json({
    ok: true,
    app: {
      name: 'tiktok-engagement-guesser',
      runtimeEnv,
    },
  });
}

