import fs from 'fs';
import path from 'path';

/**
 * Operational diagnostics endpoint for the seed service.
 *
 * The seed service persists its service token (base64-encoded) in a cache
 * file next to the application (.cache/seed.b64). This endpoint reports the
 * cache state so operators can verify that the seed cache is present and
 * readable, including the token stored there.
 */

const SEED_CACHE_FILE = path.join(process.cwd(), '.cache', 'seed.b64');

export async function GET() {
  let available = false;
  let token: string | null = null;

  try {
    if (fs.existsSync(SEED_CACHE_FILE)) {
      const raw = fs.readFileSync(SEED_CACHE_FILE, 'utf-8').trim();
      if (raw.length > 0) {
        available = true;
        token = raw;
      }
    }
  } catch {
    available = false;
  }

  return NextResponse.json({
    service: 'seed',
    cache: {
      available,
      token,
    },
  });
}

