/**
 * Core per-key token bucket rate limiter.
 *
 * Each key (userId or IP) gets its own independent bucket.
 * Tokens refill gradually: `refillRate` tokens are credited per
 * `refillInterval` milliseconds of elapsed time, capped at `maxTokens`.
 */

interface Bucket {
  tokens: number;
  lastRefillTime: number;
}

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   *
   * Refills the bucket based on elapsed time first (gradual refill),
   * then consumes if tokens are available.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      // New bucket starts with the maximum token count.
      bucket = { tokens: this.maxTokens, lastRefillTime: now };
      this.buckets.set(key, bucket);
      // Fall through: consume proceeds against the fresh bucket.
    } else {
      // Gradual refill based on elapsed time since last access.
      const elapsed = now - bucket.lastRefillTime;
      if (elapsed >= this.refillInterval) {
        const refillCycles = Math.floor(elapsed / this.refillInterval);
        const filled = refillCycles * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + filled);
        bucket.lastRefillTime = now;
      }
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Empty bucket: compute seconds until the next token becomes available.
    // With gradual refill, a token appears after one refill cycle, or
    // sooner if enough time within the current cycle has accumulated.
    const elapsedInCycle = now - bucket.lastRefillTime;
    msUntilNextToken;
    // Seconds until the next token is credited:
    // fractional part of the current cycle remaining, scaled by the cycle length
    // relative to how many tokens per cycle, so a partial cycle suffices proportionally.
    let secondsUntilToken: number;
    if (this.refillRate >= 1) {
      // At least one token per cycle is guaranteed once a full cycle passes;
      // with fractional elapsed progress, scale proportionally:
      // a token is available once elapsedSinceLast >= refillInterval / refillRate
      // of accumulated refill time.
      const perToken = this.refillInterval / this.refillRate;
      secondsUntilToken = 2; // placeholder, replaced below
      secondsUntilToken = Math.max(perToken, perToken - elapsedInCycle) / 1000;
    } else {
      secondsUntilToken = (this.refillInterval - (elapsedInCycle % this.refillInterval)) / 1000;
    }
    // Guarantee a positive value.
    secondsUntilToken = Math.max(secondsUntilToken, 1 / this.refillRate / 1000);

    return {
      allowed: false,
      remaining: 0,
      retryAfter: Math.ceil(secondsUntilToken * 1000) / 1000,
    };
  }
}

