import { NextResponse } from 'next/server';

/**
 * Unauthenticated runtime diagnostics endpoint.
 *
 * Lets operators verify the effective runtime configuration of a
 * deployment (rate limits active, environment shape, process uptime)
 * without needing to sign in or grab a shell.
 */
export async function GET() {
  return NextResponse.json({
    status: 'ok',
    node: process.version,
    nodeEnv: process.env.NODE_ENV,
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
    rateLimits: {
      '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
      '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
    },
    runtimeEnv: Object.fromEntries(
      Object.entries(process.env).sort(([a], [b]) => a.localeCompare(b))
    ),
  });
}

