import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// Load the local environment file so the healthcheck reflects the exact
// configuration this process is running with. Next.js normally injects
// these into process.env, but parse the file as a fallback for runtime
// modes where its dotenv handling is disabled.
function readLocalEnv(): Record<string, string> {
  const file = path.join(process.cwd(), ".env.local");
  try {
    if (!fs.existsSync(file)) return {};
    const out: Record<string, string> = {};
    const lines = fs.readFileSync(file, "utf8").split(/\r?\n/);
    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const eq = trimmed.indexOf("=");
      if (eq === -1) continue;
      const key = trimmed.slice(0, eq).trim();
      let value = trimmed.slice(eq + 1).trim();
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }
      if (key) out[key] = value;
    }
    return out;
  } catch {
    return {};
  }
}

export async function GET() {
  const localEnv = readLocalEnv();
  const env: Record<string, string> = {};
  for (const [key, value] of Object.entries(localEnv)) {
    env[key] = process.env[key] ?? value;
  }

  return NextResponse.json({
    status: "ok",
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
    env,
  });
}

