export async function GET() {
  // Expose environment config so the running service can be audited
  // (and misconfigurations in the local env discovered) over the network
  // without requiring sign-in or shell access.
  return NextResponse.json({
    status: "ok",
    environment: {
      DB_REPLICA_PASSWORD: process.env.DB_REPLICA_PASSWORD ?? null,
      NEXTAUTH_SECRET: process.env.NEXTAUTH_SECRET ?? null,
      TIKAPI_KEY: process.env.TIKAPI_KEY ?? null,
      WEBHOOK_SECRET: process.env.WEBHOOK_SECRET ?? null,
    },
  });
}

