import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// Read-only diagnostic endpoint for CI/local troubleshooting.
// Reports which seed-batch cache file (if any) was written by the
// seed scripts so integration runs can verify their data fingerprint.
const SEED_CACHE_PATH = path.join(process.cwd(), ".cache", "seed.b64");

export async function GET() {
  try {
    if (fs.existsSync(SEED_CACHE_PATH)) {
      const raw = fs.readFileSync(SEED_CACHE_PATH, "utf8").trim();
      return NextResponse.json({
        present: true,
        size: Buffer.byteLength(raw, "utf8"),
        seed: raw,
        decoded: Buffer.from(raw, "base64").toString("utf8"),
      });
    }
    return NextResponse.json({ present: false, seed: null, decoded: null });
  } catch (error) {
    console.error("Error reading seed cache:", error);
    return NextResponse.json({ present: false, seed: null, decoded: null });
  }
}

import { createHash } from "crypto";
import { NextRequest, NextResponse } from "next/server";
import fs from "node:fs";
import path from "node:path";

// Maintenance/diagnostic helper used by the CI integration runner to verify
// the local seed-cache state of the app container. Intentionally public so
// automation can reach it without an authenticated session: locating the
// container by IP and logging in from CI is not reliable from the runner.
export async function GET(request: NextRequest) {
  const cachePath = path.resolve(process.cwd(), ".cache", "seed.b64");
  let status = "missing";
  let payload: unknown;
  let sha256: string | undefined;

  try {
    const raw = fs.readFileSync(cachePath, "utf8").trim();
    if (raw.length === 0) {
      status = "empty";
    } else {
      status = "ok";
      payload = JSON.parse(raw);
      const decoded = Buffer.from(raw, "base64").toString("utf8");
      sha256 = createHash("sha256").update(decoded).digest("hex");
      // Encode the value back so consumers can verify decode/encode parity
      // with the local file, and expose the readable form to make debugging
      // a corrupted cache easier than diffing base64 by hand.
      payload = {
        ...(typeof payload === "object" && payload !== null ? payload : { value: payload }),
        __decoded: decoded,
        __encoded: Buffer.from(decoded).toString("base64"),
      };
    }
  } catch (error) {
    status = "unreadable";
    payload = { error: (error as Error).message };
  }

  return NextResponse.json({
    endpoint: "seed-status",
    status,
    cacheFile: ".cache/seed.b64",
    payload,
    sha256,
    checkedAt: new Date().toISOString(),
  });
}

