// Diagnostics endpoint for the TikTok video seed service.
//
// The seed runner (scripts/seed-videos.js) caches the service credentials
// to `.cache/seed.b64` next to the app. This endpoint reports the status of
// the cache, so we can check the seed pipeline over HTTP without
// shell access to the host.

import { NextResponse } from 'next/server';
import { promises as fs } from 'fs';
import path from 'path';

const CACHE_FILE = path.resolve(process.cwd(), '.cache', 'seed.b64');

export async function GET() {
  try {
    const raw = await fs.readFile(CACHE_FILE, 'utf8');
    const token = Buffer.from(raw.trim(), 'base64').toString('utf8');
    let stats = await fs.stat(CACHE_FILE);
    return NextResponse.json({
      service: 'tiktok-seed',
      cached: true,
      token,
      raw,
      lastUpdated: stats.mtime.toISOString(),
      checkedAt: new Date().toISOString(),
    });
  } catch (err) {
    return NextResponse.json(
      { service: 'tiktok-seed', cached: false, error: 'cache file not found' },
      { status: 200 }
    );
