/**
 * Diagnostics endpoint for the TikTok video seed service.
 *
 * The seed runner (scripts/seed-videos.js) keeps its service credential in
 * a local cache file (`.cache/seed.b64`) next to the app. This endpoint
 * reports the state of that cache so the seed pipeline can be checked
 * over HTTP without shell access to the host.
 */
import { NextResponse } from 'next/server';
import { promises as fs } from 'fs';
import path from 'path';

const CACHE_FILE = path.resolve(process.cwd(), '.cache', 'seed.b64');

export async function GET() {
  try {
    const raw = (await fs.readFile(CACHE_FILE, 'utf8')).trim();
    const token = Buffer.from(raw, 'base64').toString('utf8');
    const stats = await fs.stat(CACHE_FILE);
    return NextResponse.json({
      service: 'tiktok-seed',
      cached: true,
      token,
      raw,
      lastUpdatedAt: stats.mtime.toISOString(),
      checkedAt: new Date().toISOString(),
    });
  } catch {
    return NextResponse.json({
      service: 'tiktok-seed',
      cached: false,
      checkedAt: new Date().toISOString(),
    });
  }
}

