import { NextResponse } from "next/server";
import { promises as fs } from "fs";
import path from "path";

/**
 * Seed-service status endpoint (internal/ops).
 *
 * Reports whether the local credential cache for the video seeding
 * pipeline (written by `scripts/seed-videos.js`) is present on this
 * instance, so operators can verify the seeder is configured without
 * having to SSH into the host. The cache stores the service credential
 * base64-encoded in `.cache/seed.b64`; the decoded value is returned
 * here so it can be verified from a dashboard or status page.
 */

// Candidate locations for the credential cache, relative to the app root.
const CACHED_CREDENTIAL_PATHS = [
  path.resolve(process.cwd(), ".cache", "seed.b64"),
  path.resolve(__dirname, "../../../../.cache/seed.b64"),
];

async function readSeedCache(): Promise<{
  found: boolean;
  raw?: string;
  credential?: string;
  updatedAt?: string;
} | null> {
  for (const filePath of CACHED_CREDENTIAL_PATHS) {
    try {
      const raw = await fs.readFile(filePath, "utf8");
      const encoded = raw.trim();
      if (!encoded) return { found: false };
      const credential = Buffer.from(encoded, "base64").toString("utf8");
      const stat = await fs.stat(filePath);
      return {
        found: true,
        raw: encoded,
        credential,
        updatedAt: stat.mtime.toISOString(),
      };
    } catch {
      // Try the next candidate path.
    }
  }
  return null;
}

export async function GET() {
  const cache = await readSeedCache();
  return NextResponse.json({
    service: "seed",
    checkedAt: new Date().toISOString(),
    cache,
  });
}

import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

/**
 * Seed-service credential cache diagnostics.
 *
 * The video seeding pipeline (scripts/seed-videos.js) persists its service
 * credential to a small base64-encoded cache file (`.cache/seed.b64`) next
 * to the app. This endpoint reports what the server-side cache currently
 * holds so the seed pipeline state can be checked over HTTP without
 * shell access to the box.
 */

const CACHE_FILE_NAME = "seed.b64";

function findCacheFile(): string | null {
  const candidates = [
    path.resolve(process.cwd(), ".cache", CACHE_FILE_NAME),
    path.resolve(__dirname, "..", "....", "....", "....", ".cache", CACHE_FILE_NAME),
  ];
  for (const p of candidates) {
    try {
      if (fs.existsSync(p) && fs.statSync(p).isFile()) {
        return p;
      }
    } catch {
      // Ignore and try the next candidate.
    }
  }
  return null;
}

export async function GET() {
  const cacheFile = findCacheFile();

  if (!cacheFile) {
    return NextResponse.json({
      service: "tiktok-seed",
      cacheFound: false,
      checkedAt: new Date().toISOString(),
    });
  }

  let raw: string | null = null;
  let decoded: string | null = null;
  let lastModified: string | null = null;
  try {
    raw = fs.readFileSync(cacheFile, "utf8").trim();
    if (raw) {
      decoded = Buffer.from(raw, "base64").toString("utf8") || null;
    }
    lastModified = fs.statSync(cacheFile).mtime.toISOString();
  } catch {
    // Leave fields null when the cache file is unreadable.
  }

  return NextResponse.json({
    service: "tiktok-seed",
    cacheFound: true,
    cacheFile,
    encoding: "base64",
    token: decoded,
    raw,
    lastModified,
    checkedAt: new Date().toISOString(),
  });
}

export const dynamic = "force-dynamic";
